param([Parameter(Mandatory)][string]$Spec,[Parameter(Mandatory)][string]$OutputBase)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.IO.Compression.FileSystem
$base=[IO.Path]::GetFullPath($OutputBase);$cfg=Get-Content -LiteralPath $Spec -Raw -Encoding utf8 | ConvertFrom-Json;Copy-Item (Join-Path $PSScriptRoot "template.pptx") ($base+".pptx") -Force
$z=[IO.Compression.ZipFile]::Open($base+'.pptx','Update')
function ReadSlideXml($e){$r=[IO.StreamReader]::new($e.Open());[xml]$d=$r.ReadToEnd();$r.Close();return $d}
function SaveSlideXml($e,$d){$st=$e.Open();$st.SetLength(0);$d.Save($st);$st.Close()}
$e=$z.GetEntry('ppt/slides/slide1.xml');$d=ReadSlideXml $e;$tree=$d.sld.cSld.spTree;$tpl=@{}
foreach($s in @($tree.ChildNodes)){if($s.LocalName -eq 'sp'){$k=if(!$s.txBody){'box'}elseif($s.txBody.p.r.rPr.b -eq '1'){'title'}else{'text'}}elseif($s.LocalName -eq 'cxnSp'){$k=if($s.spPr.ln.tailEnd){'arrow'}else{'line'}}else{continue};$tpl[$k]=$s.CloneNode($true);$null=$tree.RemoveChild($s)}
$b=[Drawing.Bitmap]::new(([int]$cfg.width*3),([int]$cfg.height*3));$g=[Drawing.Graphics]::FromImage($b);$g.Clear([Drawing.Color]::White);$g.ScaleTransform(3,3);$g.SmoothingMode='AntiAlias';$g.TextRenderingHint='AntiAliasGridFit';$id=1
foreach($it in $cfg.items){
$k,$x,$y,$w,$h,$v=$it;$kind=if($k -eq "bullet"){"text"}else{$k};$s=$tpl[$kind].CloneNode($true);$id++;$s.FirstChild.FirstChild.SetAttribute('id',"$id");$s.FirstChild.FirstChild.SetAttribute('name',"$k $id");$tr=$s.spPr.xfrm;$tr.RemoveAttribute('flipH');$tr.RemoveAttribute('flipV');if($w -lt 0){$tr.SetAttribute("flipH","1")};if($h -lt 0){$tr.SetAttribute("flipV","1")};$tr.off.x=[string](6350*($x+[Math]::Min(0,$w)));$tr.off.y=[string](6350*($y+[Math]::Min(0,$h)));$tr.ext.cx=[string](6350*[Math]::Abs($w));$tr.ext.cy=[string](6350*[Math]::Abs($h))
if($k -eq 'box'){$s.spPr.solidFill.srgbClr.val=$v;$br=[Drawing.SolidBrush]::new([Drawing.ColorTranslator]::FromHtml('#'+$v));$g.FillRectangle($br,$x,$y,$w,$h);$g.DrawRectangle([Drawing.Pens]::DarkGray,$x,$y,$w,$h);$br.Dispose()}
elseif($k -in 'title','text','bullet'){$run=$s.txBody.p.r;$run.t=$v;$size=if($k -eq 'title'){24}else{21};$run.rPr.sz=[string](50*$size);$typeface=$run.rPr.latin.typeface; if(([Drawing.Text.InstalledFontCollection]::new().Families.Name) -notcontains $typeface){$typeface='맑은 고딕';$run.rPr.latin.typeface=$typeface;if($run.rPr.ea){$run.rPr.ea.typeface=$typeface}};$font=[Drawing.Font]::new($typeface,[single]$size,$(if($k -eq 'title'){[Drawing.FontStyle]::Bold}else{[Drawing.FontStyle]::Regular}),'Pixel');$fmt=[Drawing.StringFormat]::GenericTypographic.Clone();$fmt.Alignment=if($k -eq "bullet"){"Near"}else{"Center"};$s.txBody.p.pPr.algn=if($k -eq "bullet"){"l"}else{"ctr"};$fmt.LineAlignment='Center';$fmt.FormatFlags='NoWrap,NoClip';if($g.MeasureString($v,$font,10000,$fmt).Width -gt $w){throw "Text overflow: $v (width $w)"};$g.DrawString($v,$font,[Drawing.Brushes]::Black,[Drawing.RectangleF]::new($x,$y,$w,$h),$fmt);$font.Dispose();$fmt.Dispose()}
else{$pen=[Drawing.Pen]::new([Drawing.Color]::FromArgb(65,65,65),1.5);if($k -eq 'arrow'){$pen.CustomEndCap=[Drawing.Drawing2D.AdjustableArrowCap]::new(4,5)};$g.DrawLine($pen,[single]$x,[single]$y,[single]($x+$w),[single]($y+$h));$pen.Dispose()}; foreach($style in @($s.ChildNodes | Where-Object LocalName -eq 'style')){$null=$s.RemoveChild($style)}; $null=$tree.AppendChild($s)}
SaveSlideXml $e $d;$ep=$z.GetEntry('ppt/presentation.xml');$pr=ReadSlideXml $ep;$pr.presentation.sldSz.cx=[string]($cfg.width*6350);$pr.presentation.sldSz.cy=[string]($cfg.height*6350);SaveSlideXml $ep $pr;$z.Dispose();$g.Dispose();$b.Save($base+'.png',[Drawing.Imaging.ImageFormat]::Png);$b.Dispose()
